const sourceName = (type: string): string => SOURCE_NAMES[type] ?? type;

// ---------------------------------------------------------------------------------------------------------------
// Compute

interface SourceRow {
    name: string;
    /** chance a container holds the gun (expected copies for spawners) */
    chance: number;
    /** containers of this kind per match */
    perMatch: number;
}
interface MapResult {
    floor: number;
    drop: Readonly<Record<string, number>>;
    perMatch: number;
    fromDrops: number;
    label: string;
    special: SourceRow[];
    /** expected copies per match by source, biggest first */
    bySource: Array<{ name: string; copies: number }>;
}
interface GunRow {
    id: string;
    name: string;
    cls: string;
    tier: GunTier | null;
    dual: boolean;
    maps: Record<MapName, MapResult>;
}

/** The air drop crates shown per drop: main's tier 1, tier 2 and gold, 50v50's big military drop. */
const DROP_CRATES: Readonly<Record<MapName, Readonly<Record<string, string>>>> = {
    main: { tier1: "crate_10t1", tier2: "crate_10t2", gold: "crate_11" },
    faction: { faction: "crate_12" },
};

const tiers = tiersFrom(TIERS_FILE);
const perMap = new Map<MapName, { counts: Counts; drops: Counts; tables: Tables }>();
for (const map of MAPS) {
    const { counts, realized } = containersPerMatch(map);
    const tables = getMapDef(map).lootTable;
    perMap.set(map, { counts, drops: airdropCratesPerMatch(map), tables });
    // the analytic walk against the realized maps (they differ only by the weighted building children)
    const off = [...counts]
        .filter(([t, n]) => Math.abs((realized.get(t) ?? 0) - n) > 0.5 + 0.25 * n)
        .map(([t, n]) => `${t} ${n.toFixed(2)}/${(realized.get(t) ?? 0).toFixed(2)}`);
    console.log(`${map}: ${counts.size} container kinds; walk vs realized differ on: ${off.join(", ") || "none"}`);
}

const reachable = new Set<string>();
for (const [map, { counts, drops, tables }] of perMap) {
    for (const t of [...counts.keys(), ...drops.keys()])
        for (const g of containerYield(map, tables, t).expected.keys()) reachable.add(g);
}
// every tiered gun, the untiered ones that spawn, and the useless ones; off-map untiered guns (dev guns) are left out
const ids = [...new Set([...tiers.keys(), ...USELESS_GUNS, ...reachable])].filter(isGun);

function mapResult(map: MapName, id: string): MapResult {
    const { counts, drops, tables } = perMap.get(map)!;
    const floor = rollDist(map, tables, "tier_guns").get(id) ?? 0;
    const drop: Record<string, number> = {};
    for (const [k, crate] of Object.entries(DROP_CRATES[map]))
        drop[k] = containerYield(map, tables, crate).chance.get(id) ?? 0;
    const bySource: Counts = new Map();
    const special = new Map<string, { chanceSum: number; perMatch: number }>();
    let perMatch = 0;
    for (const [type, n] of counts) {
        const y = containerYield(map, tables, type);
        const e = (y.expected.get(id) ?? 0) * n;
        perMatch += e;
        add(bySource, y.special ? sourceName(type) : "바닥·일반 상자", e);
        const chance = y.chance.get(id) ?? 0;
        if (y.special && chance >= SPECIAL_MIN_CHANCE) {
            const s = special.get(sourceName(type)) ?? { chanceSum: 0, perMatch: 0 };
            s.chanceSum += chance * n;
            s.perMatch += n;
            special.set(sourceName(type), s);
        }
    }
    let fromDrops = 0;
    for (const [crate, n] of drops) fromDrops += (containerYield(map, tables, crate).expected.get(id) ?? 0) * n;
    add(bySource, "보급", fromDrops);
    perMatch += fromDrops;
    return {
        floor,
        drop,
        perMatch,
        fromDrops,
        label: labelOf(perMatch),
        special: [...special]
            .map(([name, s]) => ({ name, chance: s.chanceSum / s.perMatch, perMatch: s.perMatch }))
            .sort((a, b) => b.chance - a.chance),
        bySource: [...bySource]
            .filter(([, c]) => c > 0)
            .map(([name, copies]) => ({ name, copies }))
            .sort((a, b) => b.copies - a.copies),
    };
}

const tierRankOf = (t: GunTier | null): number => (t ? TIER_ORDER.indexOf(t) : -1);
const rows: GunRow[] = ids
    .map((id) => ({
        id,
        name: koItems[id] ?? (GameObjectDefs[id] as { name?: string }).name ?? id,
        cls: gunClassOf(id) ?? "useless",
        tier: tiers.get(id) ?? null,
        dual: id.endsWith("_dual"),
        maps: { main: mapResult("main", id), faction: mapResult("faction", id) },
    }))
    .sort(
        (a, b) =>
            tierRankOf(b.tier) - tierRankOf(a.tier) ||
            CLASS_ORDER.indexOf(a.cls) - CLASS_ORDER.indexOf(b.cls) ||
            b.maps.main.perMatch - a.maps.main.perMatch ||
            a.id.localeCompare(b.id),
    );

// ---------------------------------------------------------------------------------------------------------------
// Output

/** Percent with two significant digits ("–" for zero). */
function pct(p: number): string {
    if (p <= 0) return "–";
    const v = p * 100;
    if (v > 99.95) return "100%";
    return `${Number(v >= 10 ? v.toFixed(1) : v.toPrecision(2))}%`;
}
/** Copies with two significant digits below 10. */
function num(n: number): string {
    if (n <= 0) return "0";
    return n >= 10 ? n.toFixed(1) : Number(n.toPrecision(2)).toString();
}
const specialText = (s: SourceRow[], limit = 4): string =>
    s.length === 0
        ? ""
        : s
              .slice(0, limit)
              .map((r) => `${r.name} ${pct(r.chance)}`)
              .join(", ") + (s.length > limit ? ` 외 ${s.length - limit}곳` : "");

function dropsPerMatchText(map: MapName): string {
    return [...perMap.get(map)!.drops].map(([crate, n]) => `${sourceName(crate)} ${num(n)}`).join(", ");
}

const tierCell = (t: GunTier | null): string => t ?? "—";
const table = [
    "| 총 | id | class | tier | 바닥 % | 보급 1단계 % | 보급 2단계 % | 황금 % | special sources | 판당 기대 개수 (main) | 판당 기대 개수 (50v50) | label (main / 50v50) |",
    "|---|---|---|---|--:|--:|--:|--:|---|--:|--:|---|",
    ...rows.map((r) => {
        const m = r.maps.main;
        const f = r.maps.faction;
        const special = [specialText(m.special), r.dual && m.floor === 0 ? "싱글 2정 조합" : ""]
            .filter(Boolean)
            .join("; ");
        const label = m.label === f.label ? m.label : `${m.label} / ${f.label}`;
        return `| ${r.name} | \`${r.id}\` | ${CLASS_KO[r.cls] ?? r.cls} | ${tierCell(r.tier)} | ${pct(m.floor)} | ${pct(m.drop.tier1)} | ${pct(m.drop.tier2)} | ${pct(m.drop.gold)} | ${special} | ${num(m.perMatch)} | ${num(f.perMatch)} | ${label} |`;
    }),
];
const factionDrop = rows
    .filter((r) => r.maps.faction.drop.faction > 0)
    .sort((a, b) => b.maps.faction.drop.faction - a.maps.faction.drop.faction)
    .map((r) => `${r.name} ${pct(r.maps.faction.drop.faction)}`)
    .join(", ");

const tiersNote =
    arg("tiers-note") ??
    (TIERS_FILE
        ? `the tier column is read from the \`ROWS\` of \`${TIERS_FILE}\``
        : "the tier column is `tieredGuns()` of `packages/bots/src/knowledge/gunTiers.ts`");
const md = `# Gun tiers and rarity

Generated by \`node tools/research/gun-rarity.ts\` (repository root); ${tiersNote}. Do not edit the table by hand.

## Method

- **Loot.** The final loot tables of \`@rebirth/defs\` \`getMapDef(name).lootTable\` (rebirth layer applied: air drop
  tiers, the owner's 2026-10-08 weights, the new guns as normal loot; \`GUN_BETA\`'s extra floor copies left out).
  Nested \`tier_*\` rows are resolved as the sim rolls them (\`packages/sim/src/loot/lootTable.ts\`): one weighted pick
  per level, \`""\` gives nothing, a gun is one item whatever its count.
- **바닥 %.** The chance of the gun in one floor gun roll (\`tier_guns\`) of the classic map (\`main\`).
- **보급 %.** The chance that one air drop holds the gun: tier 1 (\`crate_10t1\`, with its 10 % tier 2 re-roll), tier 2
  (\`crate_10t2\`) and gold (\`crate_11\`: the \`tier_airdrop_rare\` main gun or the \`tier_airdrop_gold_bonus\` roll).
- **Special sources.** Every container or loot spawner of the map that can give the gun from a table other than the
  plain floor rolls (\`tier_world\`, \`tier_container\`) or as a fixed item, with the chance one such container holds
  it (listed from ${pct(SPECIAL_MIN_CHANCE)}; at most four, best first). Boxes that roll the floor gun table
  itself (Soviet crates, toilets, bank deposit boxes, 50v50 team crates) are listed too: floor odds, more rolls.
- **판당 기대 개수.** Maps from the sim's \`generateMap(map, seed, 4)\` (squad, "large" scale), seeds
  ${SEEDS.join(", ")}, averaged. Every top-level object is walked through its building and structure defs
  (weighted child types as chances, the map's spawn replacements), and the expected copies of every obstacle loot
  list and loot spawner are summed, as if every container on the map were opened. Players' starting gear, dead players' drops, the
  Scavenger perks' extra rolls and 50v50 role loadouts are not loot and are not counted.
- **Air drops per match.** Every scheduled drop plane of the map's \`gameConfig.planes\` (type 0), its crate picked by
  the crate weights with the circle's tier 1 share (\`tieredAirdropCrates\`). Per match: main
  ${dropsPerMatchText("main")}; 50v50 ${dropsPerMatchText("faction")}. This assumes the match reaches every drop
  circle (main 1 and 3, 50v50 2 and 4) and counts no drop called by a flare gun.
- **Label** (from 판당 기대 개수): 흔함 ≥ 3, 보통 1–3, 희귀 0.25–1, 매우 희귀 0.05–0.25, 극악 < 0.05, 안 나옴 0.
  Dual pistols that never spawn as a pair come from picking up two singles ("싱글 2정 조합").

**Coming map change.** The classic and 50v50 maps are about to grow by 20 % per side, with building counts scaled by
area. The per-match counts will then grow a little; the per-roll chances (바닥, 보급, special sources) will not change.

## Table

Sorted by tier (best first), then class, then 판당 기대 개수 on main.

${table.join("\n")}

## 50v50 air drop

50v50 has no tiered or gold drop: its drop (\`airdrop_crate_03\` → \`crate_12\`, 2 per match) rolls
\`tier_airdrop_rare\` twice and \`tier_airdrop_uncommon\` 7-8 times. Chance per drop: ${factionDrop}.
`;
writeFileSync(MD_OUT, md);
console.log(`wrote ${MD_OUT} (${rows.length} guns)`);

if (JSON_OUT) {
    const data = {
        seeds: SEEDS,
        tiersFrom: tiersNote,
        dropsPerMatch: Object.fromEntries(MAPS.map((m) => [m, dropsPerMatchText(m)])),
        rows: rows.map((r) => ({
            ...r,
            maps: Object.fromEntries(
                MAPS.map((m) => [
                    m,
                    {
                        ...r.maps[m],
                        special: r.maps[m].special.slice(0, 6),
                        bySource: r.maps[m].bySource.slice(0, 5),
                    },
                ]),
            ),
        })),
    };
    const round = (_: string, v: unknown) =>
        typeof v === "number" && !Number.isInteger(v) ? Number(v.toPrecision(4)) : v;
    writeFileSync(resolve(JSON_OUT), JSON.stringify(data, round));
    console.log(`wrote ${JSON_OUT}`);
}
